extern "C" {
u8 *m68k_memory() { return g_mem; }
u8 *m68k_modes() { return g_mode; }
u32 *m68k_bases() { return g_base; }
u8 *m68k_hookmap() { return g_hookmap; }
void m68k_callbacks(read_fn r, write_fn w, line_fn reset, line_fn ack, hook_fn hook)
{
	g_read = r; g_write = w; g_reset_cb = reset; g_ack_cb = ack; g_hook = hook;
}
// the slapstic: tests [SL_TESTS] masks and values, the pages of the bank window (each pair of 4 KB pages shows one
// 8 KB bank) and where each bank's bytes are in the memory; reset = MAME's device_reset (idle, the starting bank)
void m68k_slapstic(const u32 *masks, const u32 *values, int shift, const u32 *pages, int npages, const u32 *bankbase, int start)
{
	memcpy(g_sl_mask, masks, sizeof g_sl_mask);
	memcpy(g_sl_value, values, sizeof g_sl_value);
	g_sl_shift = shift;
	g_sl_npages = npages;
	memcpy(g_sl_pages, pages, npages * sizeof(u32));
	memcpy(g_sl_bankbase, bankbase, sizeof g_sl_bankbase);
	g_sl_state = S_IDLE;
	g_sl_on = 1;
	sl_change_bank(start);
}
u32 m68k_rom_writes(u32 *last) { last[0] = g_romwrite_addr; last[1] = g_romwrite_pc; return g_romwrites; }
u32 m68k_slapstic_changes() { return g_sl_changes; }
int m68k_slapstic_state() { return g_sl_state | (g_sl_bank << 8) | (g_sl_loaded << 16); }
void m68k_coverage(u32 *cov, const u8 *regions) { g_cov = cov; if (regions) memcpy(g_region, regions, sizeof g_region); }
void m68k_hooks_on(int on) { g_hooks_on = on; }
void m68k_create()
{
	for (int i = 0; i < 4096; i++) { g_mode[i] = PAGE_UNMAPPED; g_base[i] = i << 12; }
	g_sl_on = 0;
	if (!g_cpu) g_cpu = new glue_cpu();
	g_cpu->start();
}
void m68k_reset() { g_cpu->reset(); }
int m68k_run(int cycles) { g_stolen = 0; int r = g_cpu->run(cycles); return r - g_stolen; }
void m68k_abort() { int &ic = g_cpu->icount(); if (ic > 0) { g_stolen += ic; ic = 0; } }
int m68k_executed(int n) { return n - g_stolen - g_cpu->icount(); }
u8 *m68k_exclmap() { return g_exclmap; }
void m68k_budget(u32 count, u32 limit) { g_count = count; g_limit = limit; }
u32 m68k_counted() { return g_count; }
int m68k_icount() { return g_cpu->icount(); }
void m68k_set_icount(int n) { g_cpu->icount() = n; }
void m68k_set_input(int line, int state) { g_cpu->set_input(line, state); }
u32 m68k_get(int r) { return g_cpu->get(r); }
void m68k_set(int r, u32 v) { g_cpu->set(r, v); }
void m68k_trace(int on) { if (on && !g_trace) { g_trace_cap = 1 << 16; g_trace = (u32 *)malloc(g_trace_cap * sizeof(u32)); g_trace_len = 0; } else if (!on && g_trace) { free(g_trace); g_trace = nullptr; } }
u32 *m68k_trace_buf() { return g_trace; }
int m68k_trace_len() { return g_trace_len; }
void m68k_trace_clear() { g_trace_len = 0; }
}
